pattern.code_snippet:
# Unbalanced entries in period (start_date, end_date)
domain = [
    ('move_id.state', '=', 'posted'),
    ('date', '>=', start_date),
    ('date', '<=', end_date),
]
lines = env['account.move.line'].search(domain)
by_move = {}
for line in lines:
    mid = line.move_id.id
    if mid not in by_move:
        by_move[mid] = {'debit': 0, 'credit': 0, 'move': line.move_id}
    by_move[mid]['debit'] += line.debit
    by_move[mid]['credit'] += line.credit
result = []
for mid, data in by_move.items():
    m = data['move']
    diff = abs(data['debit'] - data['credit'])
    if diff > 0.01:
        result.append({
            'asiento': m.name,
            'fecha': str(m.date),
            'debe': data['debit'],
            'haber': data['credit'],
            'diferencia': data['debit'] - data['credit']
        })
result = sorted(result, key=operator.itemgetter('fecha'))
result
